function mapAttribution(){return `<p class="map-attribution">${lang==='zh'?'底图':'Base map'}: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth</a>${lang==='zh'?'（公共领域）':' (public domain)'}. ${lang==='zh'?'海岸线、湖泊与地名：包含取自 <a href="https://data.linz.govt.nz/" target="_blank" rel="noopener noreferrer">LINZ Data Service</a> 并按 <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> 许可再利用的数据（NZ Coastlines and Islands Polygons (Topo 1:50k)、NZ Lake Polygons (Topo 1:50k)、NZ Place Names (NZGB)）；经重新投影和绘制。':'Coastlines, lakes and place names: contains data sourced from the <a href="https://data.linz.govt.nz/" target="_blank" rel="noopener noreferrer">LINZ Data Service</a> licensed for reuse under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> (NZ Coastlines and Islands Polygons (Topo 1:50k), NZ Lake Polygons (Topo 1:50k), NZ Place Names (NZGB)); reprojected and restyled.'}</p>`}
function lineKey(mode){return ['ferry','rail'].includes(mode)?'transit':mode}
function mapLegend(modes=['walk','cycle','drive','transit'],detailed=false){return `<div class="map-legend">${modes.map(m=>`<span><svg viewBox="0 0 42 12" aria-hidden="true"><path class="map-line map-line-${m}" d="M2 6 Q15 5 23 6 T40 6"/></svg>${t(detailed&&m==='transit'?'bus':m)}</span>`).join('')}</div>`}
